function kConcatenationMaxSum(arr, k) {
  const MOD = 1000000007;
  let best = 0;
  let current = 0;
  const rounds = Math.min(k, 2);

  for (let round = 0; round < rounds; round++) {
    for (const value of arr) {
      current = Math.max(current + value, 0);
      best = Math.max(best, current);
    }
  }

  let total = 0;
  for (const value of arr) {
    total += value;
  }
  if (k > 2 && total > 0) {
    best += (k - 2) * total;
  }
  return best % MOD;
}

