function kConcatenationMaxSum(arr, k) {
  const n = arr.length;
  const suffix = new Array(n + 1).fill(0); // suffix[i] = arr[i] + ... + arr[n - 1]
  const prefix = new Array(n + 1).fill(0); // prefix[j] = arr[0] + ... + arr[j - 1]
  for (let i = n - 1; i >= 0; i--) suffix[i] = suffix[i + 1] + arr[i];
  for (let j = 1; j <= n; j++) prefix[j] = prefix[j - 1] + arr[j - 1];
  const total = prefix[n];
  let answer = 0; // the empty stretch
  // Stretches inside one copy.
  for (let i = 0; i < n; i++) {
    let sum = 0;
    for (let j = i; j < n; j++) { sum += arr[j]; answer = Math.max(answer, sum); }
  }
  // Stretches that start at i in some copy, cover m whole copies, then take arr[0..j) of the next copy.
  // m runs from 0 to k - 2 and the total is linear in m, so its two ends cover every case.
  if (k >= 2) {
    for (let i = 0; i < n; i++)
      for (let j = 0; j <= n; j++)
        for (const m of [0, k - 2]) answer = Math.max(answer, suffix[i] + m * total + prefix[j]);
  }
  return answer % 1000000007;
}

