function generate(rand, size) {
  if (size === 'large') {
    const n = 1500 + Math.floor(rand() * 501);
    const center = Math.floor(rand() * 6001) - 3000;
    const arr = Array.from({ length: n }, () => Math.max(-10000, Math.min(10000, center + Math.floor(rand() * 20001) - 10000)));
    const k = 1 + Math.floor(rand() * 100000);
    return [arr, k];
  }
  const n = 1 + Math.floor(rand() * 6);
  const shift = Math.floor(rand() * 7) - 3;
  const arr = Array.from({ length: n }, () => Math.floor(rand() * 11) - 5 + shift);
  const k = rand() < 0.2 ? 1 + Math.floor(rand() * 100000) : 1 + Math.floor(rand() * 5);
  return [arr, k];
}
